import { Injectable, signal, computed } from '@angular/core';
import { ParameterType, PARAMETER_LIBRARY } from '../models/parameter-library.model';

const STORAGE_KEY = 'dwsv_parameter_library';
const OVERRIDES_STORAGE_KEY = 'dwsv_parameter_overrides';

/**
 * Manages the reusable parameter type library.
 * Built-in types are always available; custom types are persisted to localStorage.
 * Built-in types can have field-level overrides (label, description, defaultValue, placeholder).
 */
@Injectable({ providedIn: 'root' })
export class ParameterLibraryService {
  private _customTypes = signal<ParameterType[]>([]);
  private _builtInOverrides = signal<Record<string, Partial<ParameterType>>>({});

  /** All available parameter types (built-in with overrides applied + custom) */
  readonly allTypes = computed(() => {
    const overrides = this._builtInOverrides();
    const builtIns = PARAMETER_LIBRARY.map(t => {
      const override = overrides[t.key];
      return override ? { ...t, ...override, key: t.key } : t;
    });
    return [...builtIns, ...this._customTypes()];
  });

  constructor() {
    this.loadFromStorage();
  }

  /** Get a parameter type by its key */
  getType(key: string): ParameterType | undefined {
    return this.allTypes().find(t => t.key === key);
  }

  /** Add a custom parameter type */
  addCustomType(type: ParameterType): void {
    const existing = this._customTypes();
    if (existing.some(t => t.key === type.key) || PARAMETER_LIBRARY.some(t => t.key === type.key)) {
      return;
    }
    this._customTypes.set([...existing, type]);
    this.saveToStorage();
  }

  /** Update a custom parameter type */
  updateCustomType(key: string, updates: Partial<ParameterType>): void {
    this._customTypes.update(types =>
      types.map(t => t.key === key ? { ...t, ...updates, key } : t)
    );
    this.saveToStorage();
  }

  /** Remove a custom parameter type */
  removeCustomType(key: string): void {
    if (PARAMETER_LIBRARY.some(t => t.key === key)) return;
    this._customTypes.update(types => types.filter(t => t.key !== key));
    this.saveToStorage();
  }

  /** Check if a key belongs to a built-in type */
  isBuiltIn(key: string): boolean {
    return PARAMETER_LIBRARY.some(t => t.key === key);
  }

  /** Get override for a built-in parameter type, if any */
  getBuiltInOverride(key: string): Partial<ParameterType> | undefined {
    return this._builtInOverrides()[key];
  }

  /** Set field-level overrides for a built-in parameter type */
  setBuiltInOverride(key: string, overrides: Partial<ParameterType>): void {
    if (!this.isBuiltIn(key)) return;
    this._builtInOverrides.update(o => ({ ...o, [key]: overrides }));
    this.saveOverridesToStorage();
  }

  /** Clear all overrides for a built-in parameter type */
  clearBuiltInOverride(key: string): void {
    this._builtInOverrides.update(o => {
      const copy = { ...o };
      delete copy[key];
      return copy;
    });
    this.saveOverridesToStorage();
  }

  /** Export all custom types and built-in types that have overrides */
  exportAllTypes(): ParameterType[] {
    const overrides = this._builtInOverrides();
    const overriddenBuiltIns = PARAMETER_LIBRARY
      .filter(t => overrides[t.key])
      .map(t => ({ ...t, ...overrides[t.key], key: t.key }));
    return [...overriddenBuiltIns, ...this._customTypes()];
  }

  /**
   * Import parameter types.
   * - If the key matches a built-in type, the type is imported as an override.
   * - If the key is new, it is added as a custom type.
   * - If the key already exists as a custom type, it is skipped.
   */
  importTypes(types: ParameterType[]): { imported: number; skipped: number } {
    let imported = 0;
    let skipped = 0;
    const currentCustom = this._customTypes();
    const newCustom: ParameterType[] = [];
    const overrideUpdates: Record<string, Partial<ParameterType>> = {};

    for (const type of types) {
      if (this.isBuiltIn(type.key)) {
        const { key, ...rest } = type;
        overrideUpdates[key] = rest;
        imported++;
      } else if (currentCustom.some(t => t.key === type.key)) {
        skipped++;
      } else {
        newCustom.push(type);
        imported++;
      }
    }

    if (newCustom.length > 0) {
      this._customTypes.set([...currentCustom, ...newCustom]);
      this.saveToStorage();
    }

    if (Object.keys(overrideUpdates).length > 0) {
      this._builtInOverrides.update(current => ({ ...current, ...overrideUpdates }));
      this.saveOverridesToStorage();
    }

    return { imported, skipped };
  }

  private loadFromStorage(): void {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this._customTypes.set(JSON.parse(stored));
      }
    } catch {
      // Ignore parse errors
    }
    try {
      const stored = localStorage.getItem(OVERRIDES_STORAGE_KEY);
      if (stored) {
        this._builtInOverrides.set(JSON.parse(stored));
      }
    } catch {
      // Ignore parse errors
    }
  }

  private saveToStorage(): void {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this._customTypes()));
  }

  /** Replace all custom types (for raw config editing) */
  replaceCustomTypes(types: ParameterType[]): void {
    this._customTypes.set(types);
    this.saveToStorage();
  }

  /** Replace all built-in overrides (for raw config editing) */
  replaceOverrides(overrides: Record<string, Partial<ParameterType>>): void {
    this._builtInOverrides.set(overrides);
    this.saveOverridesToStorage();
  }

  private saveOverridesToStorage(): void {
    localStorage.setItem(OVERRIDES_STORAGE_KEY, JSON.stringify(this._builtInOverrides()));
  }
}
