/**
 * Parameter Library Models
 *
 * Reusable parameter type definitions that can be shared across
 * multiple service definitions. For example, a "facility" parameter
 * type is defined once with its list of options and reused by any
 * service that needs a facility input.
 */

/** Supported input types for parameter fields */
export type ParameterInputType = 'text' | 'datetime' | 'date' | 'time' | 'number' | 'select' | 'hidden';

/**
 * A reusable parameter type definition.
 * These live in the parameter library and are referenced by service definitions.
 */
export interface ParameterType {
  /** Unique key for this parameter type (e.g., 'facility', 'fin', 'event_set') */
  key: string;

  /** Display label (e.g., 'Facility', 'FIN') */
  label: string;

  /** Input type for rendering the appropriate form control */
  inputType: ParameterInputType;

  /** Description shown as help text */
  description: string;

  /** Default value if none provided */
  defaultValue?: string;

  /** Available options for 'select' type */
  options?: SelectOption[];

  /** Placeholder text for the input */
  placeholder?: string;

  /** Whether empty string is a valid value (for optional positional params) */
  allowEmpty?: boolean;

  /** Format string for converting picker values to CCL-compatible strings */
  cclFormat?: string;

  /** Quick-select presets for datetime/date/time fields */
  presets?: DateTimePreset[];

  /** Send value without ^caret^ quoting (for numeric CCL prompts like i2/i4/f8) */
  unquoted?: boolean;
}

/** Option for select-type parameters */
export interface SelectOption {
  label: string;
  value: string;
}

/** Named preset for quick-setting datetime/date/time fields */
export interface DateTimePreset {
  label: string;
  /** Named preset key resolved at runtime (e.g., 'yesterday_start', 'today_end') */
  preset: string;
}

